package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        // length 6, offset 0. buffer[end+1] is out of bounds in the provided code logic 
        // if length is exactly buffer.length. 
        // Looking at the code: byte trailer = buffer[end + 1]; 
        // This implies the buffer must be at least length + 2.
        byte[] paddedBuffer = new byte[10];
        System.arraycopy("000123".getBytes(), 0, paddedBuffer, 0, 6);
        // paddedBuffer[7] is 0 (NUL)

        long result = TarUtils.parseOctal(paddedBuffer, 0, 6);
        assertEquals(83L, result); // 123 in octal is 83
    }
















}

