import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen1Test {















    @Test
    public void testParseOctal_LargeValue() {
        byte[] buffer = new byte[20];
        // Max long in octal is roughly 17 octal digits
        String largeOctal = "7777777777777777"; 
        System.arraycopy(largeOctal.getBytes(), 0, buffer, 0, largeOctal.length());
        buffer[largeOctal.length() + 1] = 0; 

        long result = TarUtils.parseOctal(buffer, 0, largeOctal.length());
        assertTrue(result > 0);
    }


}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen1Test {

















    @Test
    public void testParseOctal_OffsetHandling() {
        byte[] buffer = "abc00077".getBytes();
        // offset 3, length 5 -> "00077"
        // buffer[end+1] is buffer[3+5+1] = buffer[9]
        byte[] padded = new byte[10];
        System.arraycopy(buffer, 0, padded, 0, 8);
        padded[9] = 0;

        long result = TarUtils.parseOctal(padded, 3, 5);
        assertEquals(63L, result); // 77 octal is 63
    }
}
